{{- range $repo := .Values.repos}}
apiVersion: v1
kind: Secret
metadata:
  name: helm-repo-{{$repo.name}}
  namespace: argocd
  labels:
    argocd.argoproj.io/secret-type: repository
stringData:
  url: {{$repo.url}}
  name: {{$repo.name}}
  type: helm
{{- if hasPrefix "oci://" $repo.url }}
  enableOCI: "true"
{{- end }}
---
{{ end}}
{{- range $app := .Values.apps }}
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  finalizers:
    - resources-finalizer.argocd.argoproj.io
  name: {{ $app.name }}
  namespace: argocd
  annotations:
    argocd.argoproj.io/compare-options: IgnoreExtraneous
  labels:
    argocd.argoproj.io/instance: app-of-apps
spec:
  destination:
    namespace: {{ $app.namespace | default "default"  }}
    server: {{ $app.server  | default "https://kubernetes.default.svc"}}
  project: default
  source:
    {{- if hasKey $app "chart" }}
    chart: {{ $app.chart }}
    repoURL: {{ $app.repoURL }}
    targetRevision: {{ $app.targetRevision }}
    {{- if or (hasKey $app "valueFile") (hasKey $app "values") (hasKey $app "parameters") }}

