	@echo ""
	@echo "=== Prefect Pods ==="
	@kubectl get pods -n prefect 2>/dev/null || echo "No pods in prefect namespace"
	@echo ""
	@echo "=== ArgoCD Apps ==="
	@kubectl get applications -n argocd 2>/dev/null || echo "No ArgoCD apps"

# === Workflow Execution ===

# List of available workflows (update when adding new workflows)
WORKFLOWS := github reddit amazon youtube crunchyroll google_drive discord twitter

# Prerequisite checks
check-prereqs-python:
	@if [ ! -d ".venv" ]; then \
		echo "Error: Virtual environment not found. Run 'uv venv' first."; \
		exit 1; \
	fi

check-prereqs-docker:
	@if ! docker image inspect $(IMAGE):latest >/dev/null 2>&1; then \
		echo "Error: Docker image not found. Run 'make push' first."; \
		exit 1; \
	fi
	@if [ ! -f ".env" ]; then \
		echo "Warning: .env file not found. Workflows may fail without credentials."; \
	fi

check-prereqs-k8s:
	@if ! kubectl cluster-info >/dev/null 2>&1; then \
		echo "Error: Kubernetes cluster not running. Run 'make cluster-up' first."; \
		exit 1; \
	fi
	@if ! kubectl get svc -n prefect prefect-server >/dev/null 2>&1; then \
		echo "Error: Prefect server not found. Run 'make setup' first."; \
		exit 1; \
	fi
	@echo "Hint: Ensure 'make port-forward-prefect' is running in another terminal."

# Validate workflow exists
validate-workflow:
	@if [ -z "$(WORKFLOW_NAME)" ]; then \
		echo "Error: No workflow specified."; \
		echo ""; \
		$(MAKE) workflow-help; \
		exit 1; \
	fi
	@if ! echo "$(WORKFLOWS)" | grep -qw "$(WORKFLOW_NAME)"; then \
		echo "Error: Unknown workflow '$(WORKFLOW_NAME)'"; \
		echo "Available workflows: $(WORKFLOWS)"; \
		exit 1; \
	fi
	@if [ ! -f "workflows/$(WORKFLOW_NAME).py" ]; then \
		echo "Error: workflows/$(WORKFLOW_NAME).py not found"; \
		exit 1; \
	fi

# Main workflow execution dispatcher
workflow:
	@if [ -z "$(word 2,$(MAKECMDGOALS))" ]; then \
		$(MAKE) workflow-help; \
		exit 1; \
	fi
	@if [ "$(word 3,$(MAKECMDGOALS))" = "docker" ]; then \
		$(MAKE) workflow-docker WORKFLOW_NAME=$(word 2,$(MAKECMDGOALS)); \
	elif [ "$(word 3,$(MAKECMDGOALS))" = "k8s" ]; then \
		$(MAKE) workflow-k8s WORKFLOW_NAME=$(word 2,$(MAKECMDGOALS)); \
	else \
		$(MAKE) workflow-python WORKFLOW_NAME=$(word 2,$(MAKECMDGOALS)); \
	fi

# Python execution (direct)
workflow-python: validate-workflow check-prereqs-python
	@echo "Running workflows/$(WORKFLOW_NAME).py with Python..."
	@source .venv/bin/activate && python workflows/$(WORKFLOW_NAME).py

# Docker execution (containerized)
workflow-docker: validate-workflow check-prereqs-docker
	@echo "Running workflows/$(WORKFLOW_NAME).py in Docker..."
	@docker run --rm \
		-v $(HOME)/aqueduct-backups:/data/backups \
		-v $(PWD)/.env:/app/.env:ro \
		--network host \
		$(IMAGE):latest \
		python workflows/$(WORKFLOW_NAME).py

# Kubernetes execution (Prefect deployment)
workflow-k8s: validate-workflow check-prereqs-k8s
	@echo "Triggering Prefect deployment: backup-$(WORKFLOW_NAME)..."
	@PREFECT_API_URL=$(PREFECT_API) prefect deployment run backup-$(WORKFLOW_NAME)
	@echo "✓ Deployment triggered. Monitor at http://localhost:4200"

# Help documentation
workflow-help:
	@echo "=== Workflow Execution Modes ==="
	@echo ""
	@echo "Usage:"
	@echo "  make workflow <name>         # Run with Python (local)"
	@echo "  make workflow <name> docker  # Run in Docker container"
	@echo "  make workflow <name> k8s     # Run in Kubernetes (Prefect)"
	@echo ""
	@echo "Available workflows:"
	@echo "  $(WORKFLOWS)" | sed 's/ /\n  /g'
	@echo ""
	@echo "Examples:"
	@echo "  make workflow github"
	@echo "  make workflow reddit docker"
	@echo "  make workflow amazon k8s"
	@echo ""
	@echo "Prerequisites:"
	@echo "  Python:  .venv exists (run 'uv venv' and 'uv pip install -e .')"
	@echo "  Docker:  Image built (run 'make push')"
	@echo "  K8s:     Cluster running + port-forward active (run 'make cluster-up' and 'make setup')"

# Allow workflow names and modes as dummy targets
%:
	@:

